    {
      "name": "Finset.sum_image",
      "module_name": "Mathlib.Algebra.BigOperators.Group.Finset.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {κ : Type u_2} {M : Type u_4} [inst : AddCommMonoid M] {f : ι → M} [inst_1 : DecidableEq ι]\n  {s : Finset κ} {g : κ → ι}, Set.InjOn g ↑s → ∑ x ∈ Finset.image g s, f x = ∑ x ∈ s, f (g x)"
    },
    {
      "name": "ENNReal.tsum_comp_le_tsum_of_injective",
      "module_name": "Mathlib.Topology.Algebra.InfiniteSum.ENNReal",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_2} {f : α → β},\n  Function.Injective f → ∀ (g : β → ENNReal), ∑' (x : α), g (f x) ≤ ∑' (y : β), g y"
    },
    {
      "name": "tsum_comp_le_tsum_of_inj",
      "module_name": "Mathlib.Topology.Algebra.InfiniteSum.ENNReal",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {β : Type u_4} {f : α → ℝ},\n  Summable f → (∀ (a : α), 0 ≤ f a) → ∀ {i : β → α}, Function.Injective i → tsum (f ∘ i) ≤ tsum f"
    },
    {
      "name": "Fintype.sum_of_injective",
      "module_name": "Mathlib.Algebra.BigOperators.Group.Finset.Basic",
      "kind": "theorem",
      "type": "∀ {M : Type u_4} {κ : Type u_6} {ι : Type u_7} [inst : Fintype ι] [inst_1 : Fintype κ] [inst_2 : AddCommMonoid M]\n  (e : ι → κ),\n  Function.Injective e →\n    ∀ (f : ι → M) (g : κ → M), (∀ i ∉ Set.range e, g i = 0) → (∀ (i : ι), f i = g (e i)) → ∑ i, f i = ∑ j, g j"
    },
    {
      "name": "Finset.sum_map",
      "module_name": "Mathlib.Algebra.BigOperators.Group.Finset.Defs",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {κ : Type u_2} {M : Type u_3} [inst : AddCommMonoid M] (s : Finset ι) (e : ι ↪ κ) (f : κ → M),\n  ∑ x ∈ Finset.map e s, f x = ∑ x ∈ s, f (e x)"
    },
    {
      "name": "Finset.sum_map'",
      "module_name": "Mathlib.Algebra.BigOperators.Group.Finset.Defs",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {κ : Type u_2} {M : Type u_3} [inst : AddCommMonoid M] (s : Finset ι) (e : ι ↪ κ),\n  (Finset.map e s).sum = fun f => ∑ x ∈ s, f (e x)"
    }
  ]
}

