      "name": "Finset.card_le_card_add_right_of_injective",
      "module_name": "Mathlib.Algebra.Group.Pointwise.Finset.Basic",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} [inst : DecidableEq α] [inst_1 : Add α] {s t : Finset α} {a : α},\n  a ∈ t → (Function.Injective fun x => x + a) → s.card ≤ (s + t).card"
    }
  ]
}

